CREATE TYPE booking_status AS ENUM ('PENDING', 'SEATS_HELD', 'PAYMENT_PENDING', 'CONFIRMING', 'CONFIRMED', 'CANCELLING', 'FAILED', 'CANCELLED', 'EXPIRED');
CREATE TYPE saga_step AS ENUM ('HOLD_SEATS', 'CREATE_PAYMENT', 'CONFIRM_SEATS', 'COMPLETE');
CREATE TYPE saga_step_status AS ENUM ('PENDING', 'COMPLETED', 'COMPENSATING', 'COMPENSATED', 'FAILED');
CREATE TABLE IF NOT EXISTS bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL, schedule_id text NOT NULL, train_id text NOT NULL, train_number text NOT NULL, train_name text NOT NULL, departure_date date NOT NULL, status booking_status NOT NULL DEFAULT 'PENDING', total_amount real NOT NULL DEFAULT 0, seat_count integer NOT NULL, from_station_id text, to_station_id text, from_seq integer, to_seq integer, idempotency_key text NOT NULL UNIQUE, payment_order_id text UNIQUE, lock_expires_at timestamp, failure_reason text, version integer NOT NULL DEFAULT 0, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS booking_seats (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, seat_id text NOT NULL, seat_number integer NOT NULL, seat_type text NOT NULL, price real NOT NULL, created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS passengers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, name text NOT NULL, age integer NOT NULL, gender text NOT NULL, seat_id text, created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS saga_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, step saga_step NOT NULL, status saga_step_status NOT NULL DEFAULT 'PENDING', request jsonb, response jsonb, error text, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS idempotency_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_key text NOT NULL UNIQUE, response jsonb, processed_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), topic text NOT NULL, key text, value jsonb NOT NULL, headers jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'PENDING', retry_count integer NOT NULL DEFAULT 0, max_retries integer NOT NULL DEFAULT 5, created_at timestamp NOT NULL DEFAULT now(), processed_at timestamp, last_error text);
